-- Room-dependent add-on prices
INSERT INTO public.hajj_addon_room_prices (addon_id, room_type, price)
SELECT a.id, v.room, v.price
FROM (VALUES
	('2027-USD', 'aziziya_family_room_supplement', 'Double', 1100),
	('2027-USD', 'aziziya_family_room_supplement', 'Triple', 550),
	('2027-USD', 'extra_medinah_night', 'Double', 850),
	('2027-USD', 'extra_medinah_night', 'Triple', 600),
	('2027-USD', 'extra_medinah_night', 'Quad', 600),
	('2027-SAR', 'aziziya_family_room_supplement', 'Double', 4000),
	('2027-SAR', 'aziziya_family_room_supplement', 'Triple', 2000),
	('2027-SAR', 'extra_medinah_night', 'Double', 3000),
	('2027-SAR', 'extra_medinah_night', 'Triple', 2200),
	('2027-SAR', 'extra_medinah_night', 'Quad', 2190)
) AS v(cat, addon, room, price)
